package com.bautruc.ecommerce.chat.application;
import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.sql.*;import java.time.Instant;import java.util.*;
import com.bautruc.ecommerce.chat.api.request.ChatMessageRequest;import com.bautruc.ecommerce.common.exception.BusinessException;import com.bautruc.ecommerce.common.security.CurrentUserProvider;import com.bautruc.ecommerce.common.time.BusinessClock;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ChatService {
 public record Conversation(Long id,Long userId,String guestName,String guestEmail,String status,Instant updatedAt,Instant closedAt){} public record Message(Long id,Long conversationId,String sender,String body,Instant createdAt){} public record ThreadView(Conversation conversation,List<Message> messages){} public record SendResult(ThreadView thread,String newGuestToken){} public record ConversationPage(List<Conversation> content,int page,int size,long totalElements,int totalPages){} private final JdbcTemplate db;private final CurrentUserProvider current;private final BusinessClock clock;
 public ChatService(JdbcTemplate db,CurrentUserProvider current,BusinessClock clock){this.db=db;this.current=current;this.clock=clock;}
 @Transactional(readOnly=true) public ThreadView mine(String cookie){var user=current.currentUser().orElse(null);String owner=owner(cookie);if(owner==null)return new ThreadView(null,List.of());Conversation c=latest(user==null?hash(owner):null,user==null?null:user.userId());return c==null?new ThreadView(null,List.of()):thread(c);}
 @Transactional public SendResult send(String cookie,ChatMessageRequest req){String token=owner(cookie);boolean fresh=token==null;if(fresh)token=UUID.randomUUID().toString();String hash=hash(token);var user=current.currentUser().orElse(null);if(user!=null&&"ADMIN".equals(user.role()))throw err("CHAT_ROLE_FORBIDDEN","Admin must use admin chat console.",HttpStatus.FORBIDDEN);lock(hash,user==null?null:user.userId());Conversation c=latest(hash,user==null?null:user.userId());Instant now=clock.now();if(c==null||!"OPEN".equals(c.status())){Long id=db.queryForObject("INSERT INTO chat_conversations(user_id,guest_token_hash,guest_name,guest_email,status,created_at,updated_at) VALUES(?,?,?,?, 'OPEN',?,?) RETURNING id",Long.class,user==null?null:user.userId(),user==null?hash:null,user==null?trim(req.guestName(),100):null,user==null?trim(req.guestEmail(),320):null,Timestamp.from(now),Timestamp.from(now));c=get(id);}Long recent=db.queryForObject("SELECT COUNT(*) FROM chat_messages WHERE conversation_id=? AND sender='CUSTOMER' AND created_at>=?",Long.class,c.id(),Timestamp.from(now.minusSeconds(10)));if(recent!=null&&recent>=3)throw err("CHAT_RATE_LIMIT","Please send messages more slowly.",HttpStatus.TOO_MANY_REQUESTS);db.update("INSERT INTO chat_messages(conversation_id,sender,body,created_at) VALUES(?,'CUSTOMER',?,?)",c.id(),body(req.body()),Timestamp.from(now));db.update("UPDATE chat_conversations SET updated_at=? WHERE id=?",Timestamp.from(now),c.id());return new SendResult(thread(get(c.id())),fresh?token:null);}
 @Transactional public ThreadView closeMine(String cookie){var user=current.currentUser().orElse(null);String token=owner(cookie);if(token==null)throw notFound();Conversation c=latest(user==null?hash(token):null,user==null?null:user.userId());if(c==null)throw notFound();return close(c.id());}
 @Transactional(readOnly=true) public ConversationPage adminList(String status,int page,int size){String s=status==null||status.isBlank()?"OPEN":status.toUpperCase(Locale.ROOT);if(!Set.of("OPEN","CLOSED").contains(s))throw err("CHAT_STATUS_INVALID","Invalid conversation status.",HttpStatus.BAD_REQUEST);int p=Math.max(0,page),n=Math.min(50,Math.max(1,size));Long total=db.queryForObject("SELECT COUNT(*) FROM chat_conversations WHERE status=?",Long.class,s);List<Conversation> rows=db.query("SELECT id,user_id,guest_name,guest_email,status,updated_at,closed_at FROM chat_conversations WHERE status=? ORDER BY updated_at DESC,id DESC LIMIT ? OFFSET ?",this::conversation,s,n,(long)p*n);long t=total==null?0:total;return new ConversationPage(rows,p,n,t,(int)((t+n-1)/n));}
 @Transactional(readOnly=true) public ThreadView adminThread(Long id){return thread(get(id));}
 @Transactional public ThreadView reply(Long id,ChatMessageRequest req){Conversation c=lockConversation(id);if(!"OPEN".equals(c.status()))throw err("CHAT_CLOSED","Conversation is closed.",HttpStatus.CONFLICT);Instant now=clock.now();db.update("INSERT INTO chat_messages(conversation_id,sender,body,created_at) VALUES(?,'ADMIN',?,?)",id,body(req.body()),Timestamp.from(now));db.update("UPDATE chat_conversations SET updated_at=? WHERE id=?",Timestamp.from(now),id);return thread(get(id));}
 @Transactional public ThreadView adminClose(Long id){return close(id);} @Transactional public int deleteExpired(){return db.update("DELETE FROM chat_conversations WHERE status='CLOSED' AND closed_at < now() - interval '60 days'");}
 private ThreadView close(Long id){lockConversation(id);Instant now=clock.now();db.update("UPDATE chat_conversations SET status='CLOSED',closed_at=?,updated_at=? WHERE id=? AND status='OPEN'",Timestamp.from(now),Timestamp.from(now),id);return thread(get(id));}
 private ThreadView thread(Conversation c){List<Message> m=db.query("SELECT id,conversation_id,sender,body,created_at FROM (SELECT id,conversation_id,sender,body,created_at FROM chat_messages WHERE conversation_id=? ORDER BY id DESC LIMIT 200) x ORDER BY id",this::message,c.id());return new ThreadView(c,m);}
 private Conversation latest(String hash,Long user){return latest(hash,user,false);}private Conversation latest(String hash,Long user,boolean lock){String q=user!=null?"user_id=?":"guest_token_hash=?";List<Conversation> r=db.query("SELECT id,user_id,guest_name,guest_email,status,updated_at,closed_at FROM chat_conversations WHERE "+q+" ORDER BY id DESC LIMIT 1"+(lock?" FOR UPDATE":""),this::conversation,user!=null?user:hash);return r.isEmpty()?null:r.get(0);}private void lock(String hash,Long user){db.queryForList("SELECT pg_advisory_xact_lock(?)",user!=null?-user:Integer.toUnsignedLong(hash.hashCode()));}
 private Conversation lockConversation(Long id){List<Conversation> r=db.query("SELECT id,user_id,guest_name,guest_email,status,updated_at,closed_at FROM chat_conversations WHERE id=? FOR UPDATE",this::conversation,id);if(r.isEmpty())throw notFound();return r.get(0);}private Conversation get(Long id){List<Conversation> r=db.query("SELECT id,user_id,guest_name,guest_email,status,updated_at,closed_at FROM chat_conversations WHERE id=?",this::conversation,id);if(r.isEmpty())throw notFound();return r.get(0);}
 private String owner(String cookie){if(current.currentUser().isPresent())return current.currentUser().get().userId().toString();if(cookie==null||cookie.length()!=36)return null;try{return UUID.fromString(cookie).toString().equals(cookie)?cookie:null;}catch(Exception e){return null;}}private String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private String body(String s){String v=s==null?"":s.trim();if(v.isEmpty()||v.length()>2000)throw err("CHAT_MESSAGE_INVALID","Message must contain 1 to 2000 characters.",HttpStatus.BAD_REQUEST);return v;}private String trim(String s,int n){return s==null||s.isBlank()?null:s.trim().substring(0,Math.min(n,s.trim().length()));}private BusinessException err(String c,String m,HttpStatus s){return new BusinessException(c,m,s);}private BusinessException notFound(){return err("CHAT_NOT_FOUND","Conversation not found.",HttpStatus.NOT_FOUND);}
 private Conversation conversation(ResultSet r,int i)throws SQLException{Object u=r.getObject("user_id");Timestamp closed=r.getTimestamp("closed_at");return new Conversation(r.getLong("id"),u==null?null:r.getLong("user_id"),r.getString("guest_name"),r.getString("guest_email"),r.getString("status"),r.getTimestamp("updated_at").toInstant(),closed==null?null:closed.toInstant());}private Message message(ResultSet r,int i)throws SQLException{return new Message(r.getLong("id"),r.getLong("conversation_id"),r.getString("sender"),r.getString("body"),r.getTimestamp("created_at").toInstant());}
}
